      "codigo_refatorado": "using System;
using UnityEngine;

namespace PerformanceAdvisor.StressTest
{
    public partial class StressTestScene : MonoBehaviour
    {
        private void Update()
        {
            if (stressCpu)
            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    var allObjects = GameObject.FindObjectsOfType<GameObject>();
                    GC.KeepAlive(allObjects);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++) SpawnOne();
            }
        }
    }
}",
      "explicacao_didatica": "O Garbage Collector (coletor de lixo da memória gerenciada) precisa pausar a execução da CPU para vasculhar e liberar objetos temporários que não estão mais sendo usados. No C#, a operação de juntar textos ('string s += ...') e a criação de novas listas ou arrays alocam memória na Heap a cada iteração. Quando acumulam muitos megabytes em um único quadro, o coletor é obrigado a rodar emergencialmente, congelando o jogo por 25.84 ms, o que ultrapassa o teto de 16.7 ms necessário para manter 60 FPS."
